  1	/* ============================================================
  2	   views/knowledge.js — Knowledge view
  3	   Section 4f of the MCP Server Dashboard SPA
  4	   Depends on: API, escapeHtml, formatDate, showLoading, showError
  5	   ============================================================ */
  6	
  7	function renderKnowledge(app) {
  8	  showLoading(app);
  9	
 10	  /* ── Confidence bucket thresholds ────────────────────────── */
 11	  var CONFIDENCE_HIGH_MIN   = 68;   /* 68–100 → High  */
 12	  var CONFIDENCE_MEDIUM_MIN = 34;   /* 34–67  → Medium */
 13	  /* 0–33 → Low */
 14	
 15	  /* ── View state ──────────────────────────────────────────── */
 16	  var allInsights     = [];
 17	  var activeTab       = 'global';   /* 'global' | 'project' */
 18	  var filterCategory  = '';
 19	  var filterProject   = '';
 20	  var filterQuery     = '';
 21	  var editingId       = null;       /* numeric id of card in edit mode */
 22	  var confirmDeleteId = null;       /* numeric id of card in delete-confirm mode */
 23	  var movingId        = null;       /* numeric id of card in move mode */
 24	
 25	  /* ── formatConfidence ────────────────────────────────────── */
 26	  function formatConfidence(value) {
 27	    var pct = Math.round(value * 100);
 28	    var label;
 29	    if (pct >= CONFIDENCE_HIGH_MIN) {
 30	      label = 'High';
 31	    } else if (pct >= CONFIDENCE_MEDIUM_MIN) {
 32	      label = 'Medium';
 33	    } else {
 34	      label = 'Low';
 35	    }
 36	    return pct + '% (' + label + ')';
 37	  }
 38	
 39	  /* ── applyFilters ────────────────────────────────────────── */
 40	  function applyFilters() {
 41	    var scopeValue = activeTab === 'global' ? 'global' : 'project';
 42	    return allInsights.filter(function (ins) {
 43	      if (ins.scope !== scopeValue) return false;
 44	      if (filterCategory && ins.category !== filterCategory) return false;
 45	      if (activeTab === 'project' && filterProject && ins.project_slug !== filterProject) return false;
 46	      if (filterQuery) {
 47	        var q = filterQuery.toLowerCase();
 48	        var titleMatch    = ins.title   && ins.title.toLowerCase().indexOf(q) !== -1;
 49	        var contentMatch  = ins.content && ins.content.toLowerCase().indexOf(q) !== -1;
 50	        var tagsMatch     = ins.tags    && ins.tags.some(function (t) { return t.toLowerCase().indexOf(q) !== -1; });
 51	        if (!titleMatch && !contentMatch && !tagsMatch) return false;
 52	      }
 53	      return true;
 54	    });
 55	  }
 56	
 57	  /* ── buildFilterBarHtml ──────────────────────────────────── */
 58	  function buildFilterBarHtml(categories, projects) {
 59	    var catOptions = categories.map(function (c) {
 60	      return '<option value="' + escapeHtml(c) + '"' + (filterCategory === c ? ' selected' : '') + '>' + escapeHtml(c) + '</option>';
 61	    }).join('');
 62	
 63	    var baseBar =
 64	      '<label for="kn-category">Category:</label>' +
 65	      '<select id="kn-category" class="form-control form-control-sm">' +
 66	        '<option value="">All categories</option>' + catOptions +
 67	      '</select>' +
 68	      '<label for="kn-query">Search:</label>' +
 69	      '<input id="kn-query" type="text" class="form-control form-control-sm" placeholder="Title, content or tag…" value="' + escapeHtml(filterQuery) + '">';
 70	
 71	    if (activeTab === 'project') {
 72	      var projOptions = projects.map(function (p) {
 73	        return '<option value="' + escapeHtml(p) + '"' + (filterProject === p ? ' selected' : '') + '>' + escapeHtml(p) + '</option>';
 74	      }).join('');
 75	      return (
 76	        '<label for="kn-project">Project:</label>' +
 77	        '<select id="kn-project" class="form-control form-control-sm">' +
 78	          '<option value="">All projects</option>' + projOptions +
 79	        '</select>' +
 80	        baseBar
 81	      );
 82	    }
 83	
 84	    return baseBar;
 85	  }
 86	
 87	  /* ── buildKnowledgeHtml ──────────────────────────────────── */
 88	  function buildKnowledgeHtml(insights) {
 89	    if (!insights.length) {
 90	      return '<p class="text-muted mt-16">No knowledge entries found.</p>';
 91	    }
 92	
 93	    return insights.map(function (ins) {
 94	      var id          = ins.id;
 95	      var isGlobal    = ins.scope === 'global';
 96	      var isEditing   = editingId === id;
 97	      var isConfirm   = confirmDeleteId === id;
 98	      var isMoving    = movingId === id;
 99	
100	      /* ── Scope badge ── */

101	      var scopeBadgeClass = isGlobal ? 'badge badge-scope-global' : 'badge badge-scope-project';
102	      var scopeLabel      = isGlobal ? 'Global' : 'Project';
103	
104	      /* ── Tags ── */
105	      var tagsHtml = '';
106	      if (ins.tags && ins.tags.length) {
107	        tagsHtml = ins.tags.map(function (t) {
108	          return '<span class="tag-chip">' + escapeHtml(t) + '</span>';
109	        }).join(' ');
110	      }
111	
112	      /* ── Content preview ── */
113	      var preview = ins.content ? ins.content.slice(0, 200) + (ins.content.length > 200 ? '…' : '') : '';
114	
115	      /* ── Superseded-by notice ── */
116	      var supersededHtml = ins.superseded_by != null
117	        ? '<p class="text-muted" style="font-size:12px">Superseded by KN-' + ins.superseded_by + '</p>'
118	        : '';
119	
120	      /* ── Inline edit form ── */
121	      if (isEditing) {
122	        var tagsValue = ins.tags ? ins.tags.join(', ') : '';
123	        var confPct   = formatConfidence(ins.confidence != null ? ins.confidence : 0);
124	        return '<div class="card" data-id="' + id + '">' +
125	          '<form id="kn-edit-form-' + id + '">' +
126	            '<div class="form-group">' +
127	              '<label class="form-label">Title</label>' +
128	              '<input id="kn-edit-title-' + id + '" class="form-control" type="text" value="' + escapeHtml(ins.title || '') + '">' +
129	            '</div>' +
130	            '<div class="form-group">' +
131	              '<label class="form-label">Content</label>' +
132	              '<textarea id="kn-edit-content-' + id + '" class="form-control" rows="6">' + escapeHtml(ins.content || '') + '</textarea>' +
133	            '</div>' +
134	            '<div class="form-group">' +
135	              '<label class="form-label">Category</label>' +
136	              '<input id="kn-edit-category-' + id + '" class="form-control" type="text" value="' + escapeHtml(ins.category || '') + '">' +
137	            '</div>' +
138	            '<div class="form-group">' +
139	              '<label class="form-label">Tags (comma-separated)</label>' +
140	              '<input id="kn-edit-tags-' + id + '" class="form-control" type="text" value="' + escapeHtml(tagsValue) + '">' +
141	            '</div>' +
142	            '<div class="form-group">' +
143	              '<label class="form-label">Confidence: <span id="kn-conf-label-' + id + '">' + escapeHtml(confPct) + '</span></label>' +
144	              '<input id="kn-edit-conf-' + id + '" class="form-control" type="range" min="0" max="1" step="0.01" value="' + (ins.confidence != null ? ins.confidence : 0) + '">' +
145	            '</div>' +
146	            '<div class="knowledge-actions">' +
147	              '<button type="submit" class="btn btn-primary btn-sm">Save</button>' +
148	              '<button type="button" class="btn btn-sm" data-action="cancel-edit" data-id="' + id + '">Cancel</button>' +
149	            '</div>' +
150	            '<div id="kn-edit-msg-' + id + '"></div>' +
151	          '</form>' +
152	        '</div>';
153	      }
154	
155	      /* ── Action buttons ── */
156	      var deleteHtml;
157	      if (isConfirm) {
158	        deleteHtml =
159	          '<span>Delete this entry?</span>' +
160	          '<button class="btn btn-danger btn-sm" data-action="confirm-delete" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-slug="' + escapeHtml(ins.project_slug || '') + '">Confirm</button>' +
161	          '<button class="btn btn-sm" data-action="cancel-delete" data-id="' + id + '">Cancel</button>';
162	      } else {
163	        deleteHtml = '<button class="btn btn-danger btn-sm" data-action="delete" data-id="' + id + '">Delete</button>';
164	      }
165	
166	      var promoteHtml = !isGlobal
167	        ? '<button class="btn btn-sm" data-action="promote" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-slug="' + escapeHtml(ins.project_slug || '') + '">Promote to Global</button>'
168	        : '';
169	
170	      var moveHtml;
171	      if (isMoving) {
